def D(h,a,b):return h+[[a,b]]
W=[
E('study','/ˈstʌdi/','学习；研究；仔细察看；书房','把注意力放到一件事上，认真看、想、练，就是 study 的共同画面；不局限于坐在教室里背书。','经古法语 estudie、estudier，接拉丁 studium 与 studēre 词族；名词与动词有各自的传入形式。',S,'study French 是学习法语；study a map 是仔细看地图；a study of sleep 是一项睡眠研究。房间 a study 则是用来读写工作的书房。','study for an exam；study a subject；a research study；in the study。','study 强调投入学习的过程；learn 强调学会或获得知识。认真 study 并不保证立刻 learn。',('I studied the map before leaving the hotel.','离开酒店前，我仔细看了地图。'),('The study examined how sleep affects memory.','这项研究考察了睡眠如何影响记忆。'),('She studies biology and often reads in her father’s study.','她学习生物学，经常在父亲的书房里看书。'),sources=['https://www.etymonline.com/word/study']),
E('student','英 /ˈstjuːdənt/；美 /ˈstuːdənt/','学生；学习者；研究某方面的人','student 的出发点是正在用心学习的人。学校提供一个常见场景，但这个词不只认学生证。','拉丁 studēns 是 studēre 的现在分词，经古法语 estudiant 传入；不是历史上从英语 study 简单裁字加 -ent。',T,'a university student 是大学生；a student of history 也可指长期钻研历史的人，并不一定在读学位。英美对学校不同阶段的习惯称呼有差别。','a medical student；a student of human nature；international students。','pupil 在英式英语常指中小学学生；student 可涵盖更广的学习者，美国尤其常用于各学段。',('She is a medical student in her final year.','她是最后一年在读的医学生。'),('He has always been a careful student of human behaviour.','他一直认真观察和研究人的行为。')),
E('studentship','英 /ˈstjuːdəntʃɪp/；美 /ˈstuːdəntʃɪp/','学生身份；研究生等的资助名额、奖学金','先是“作为学生的状态”，后来也用来称让一个人能够继续学习研究的资助安排。','student + -ship；-ship 表状态、身份，进一步用于资助学习的名额。',D(T,'英语 student + -ship → studentship','学生身份 → 学习资助、奖学金名额'),'英国大学语境常见 PhD studentship，通常是博士研究资助安排。具体是否包含学费、生活费以及持续多久，要看该项目说明。','a funded studentship；a PhD studentship；apply for a studentship。','scholarship 是较广的奖学金名称；studentship 在英国研究生资助语境尤其常见，不是“学生的船”。',('She applied for a doctoral studentship in engineering.','她申请了工程学博士研究资助。'),('The studentship covers tuition fees and provides a living allowance.','这项学生资助包含学费，并提供生活津贴。'),sources=['https://www.merriam-webster.com/dictionary/studentship']),
E('studious','英 /ˈstjuːdiəs/；美 /ˈstuːdiəs/','好学的；勤于钻研的；刻意认真的','一个人愿意把时间和心思沉进学习里，就是 studious；同样的认真也可能用在刻意安排某种态度上。','借拉丁 studiōsus，来自 studium；现代能与 study 联系，但不是直接加英语 -ous 得到的历史。',O,'a studious child 是好学的孩子。studious avoidance 却不是“好学的回避”，而是认真、刻意地避开某事。','a studious person；studious attention；studious avoidance。','studious 说勤于学习的习惯；intelligent 说理解思考能力，勤学与聪明不是同一特征。',('She was a quiet, studious child who loved the library.','她小时候安静好学，很喜欢图书馆。'),('His studious avoidance of the topic was noticeable.','他刻意回避这个话题，让人很容易注意到。'),sources=['https://www.etymonline.com/word/studious']),
E('studiously','英 /ˈstjuːdiəsli/；美 /ˈstuːdiəsli/','勤勉地；认真地；刻意地','认真做一件事是它的一面；认真控制自己不提某件事，也能用它，所以常见“刻意避开”。','studious + -ly；中古英语已有 studiousli。',D(O,'英语 studious + -ly → studiously','专注认真的 → 认真地、刻意地'),'studiously ignored 表示有意识地不理会，绝不是“学习性地忽略”。它常让读者感觉行为经过控制和安排。','studiously avoid；studiously ignore；studiously neutral。','carefully 更中性；studiously 在回避、装作中立等搭配里突出刻意用心。',('She studiously avoided mentioning the delay.','她刻意避免提到延误。'),('The apprentice studiously copied each detail of the design.','学徒认真临摹了设计中的每一个细节。'),sources=['https://www.merriam-webster.com/dictionary/studiously']),
E('understudy','英 /ˈʌndəstʌdi/；美 /ˈʌndərstʌdi/','替补演员；学习某角色以备替演','一位演员先在幕后把别人的角色学熟，需要时能接上舞台；under- 在这里带着替补、从属的位置感。','under- + study，在英语戏剧语境中形成名词与动词。',D(S,'英语 under- + study → understudy','预先学好角色以备替演；替补演员'),'替补演员要掌握角色和走位，并不等于能力差；区别在演出安排。动词可说 understudy a role 或 understudy an actor。','an understudy for the lead；understudy a role；go on as an understudy。','a stunt double 替演特技动作；an understudy 通常准备接替整个角色，职能不同。',('The understudy took over when the lead actor fell ill.','主演生病后，替补演员接演了角色。'),('She is understudying the role of the queen.','她正在学习女王这个角色，以备替演。')),
E('studio','英 /ˈstjuːdiəʊ/；美 /ˈstuːdioʊ/','工作室；录音棚、摄影棚；单间公寓','从“专心钻研的房间”走到画家、摄影师和音乐人工作的空间，再延伸到相关制作机构。','意大利 studio 原可指学习、工作房间，来自拉丁 studium；直接从意大利语借入这一支。',[H[0],['意大利 studio → 英语 studio','研习、创作的房间 → 工作室'],['英语进一步用法','录音摄影空间、制作公司；单间公寓']],'in the studio 可说在录音棚工作；a film studio 也可指制片公司。租房广告中的 studio 常是客厅卧室共用主要空间的单间公寓。','an art studio；a recording studio；a studio apartment。','study 常是住宅中的书房；studio 常为创作制作空间，或特定公寓类型，不能只按“房间”互换。',('The band spent a week in the recording studio.','乐队在录音棚里待了一周。'),('She rented a small studio near the station.','她在车站附近租了一间小型单间公寓。'),sources=['https://www.etymonline.com/word/studio']),
E('etude','英 /ˈeɪtjuːd/；美 /ˈeɪtuːd/〔也有尾重音〕','练习曲','把某种演奏技巧单独拿出来练，但把练习写成一首音乐作品，这就是 etude 的基本想法。','法语 étude“学习、研究”，经古法语 estudie 接拉丁 studium；英语也保留拼法 étude。',[H[0],['古法语 estudie → 法语 étude','学习；专门练习'],['英语 etude / étude','为练习技巧而作的乐曲']],'练习曲不等于机械练指头；有些作品同时有很强的音乐表现力，可在正式音乐会上演奏。这个词不只用于钢琴。','a piano etude；a concert etude；practise an etude。','exercise 是任何练习；etude 特别指音乐练习作品，常围绕某种技巧。',('This etude helps the pianist practise rapid scales.','这首练习曲帮助钢琴演奏者练习快速音阶。'),('She performed a concert etude at the recital.','她在独奏会上演奏了一首音乐会练习曲。'),sources=['https://www.etymonline.com/word/etude','https://en.wiktionary.org/wiki/etude#English']),
]
ROOT=dict(id='C1440',meaning='用心投入；专注学习和钻研',core='STUD = APPLY ONESELF',image='把灯光打在一件正在研究的东西上：study 是投入地看和学，student 是学习的人，studio 是专注创作的空间，etude 则把这种练习写进音乐里。',intro='拉丁 studēre 的意思比现代“上课学习”更宽，包含热衷、专心投入；名词 studium 是用心与钻研。英语从法语、意大利语和拉丁语的不同形式中，借出了几个看起来不太像的同源词。',forms='student 接拉丁现在分词 studēns；studious 接拉丁 studiōsus；study 经古法语，studio 经意大利语，etude 经现代法语。它们是不同历史支线，不是英语 study 依次变成了后面几个词。',branches=[['学习与投入','study, student, studious, studiously'],['学习身份与资助','studentship'],['预先学好角色','understudy'],['创作与音乐练习','studio, etude']],contrasts='study 是学习过程，learn 侧重学到；studious 不等于聪明。studiously avoid 是刻意回避。studio 不总是工作室，也可能是单间公寓。',practice='The studious student practised an etude in the studio while an understudy learned the lead role nearby.\n\n好学的学生在工作室练习一首练习曲，旁边一位替补演员正在熟悉主角的戏。',words=[w['word'] for w in W])
